    93			return nil, err
    94		}
    95	
    96		var opts []func(*loader.Options)
    97		if g.Project != nil {
    98			opts = append(opts, func(o *loader.Options) {
    99				o.SetProjectName(g.Project.Name, true)
   100			})
   101		}
   102	
   103		// Workaround for https://github.com/compose-spec/compose-go/issues/489.
   104		var configFiles []types.ConfigFile
   105		for _, input := range g.Inputs {
   106			content, err := os.ReadFile(input)
   107			if err != nil {
   108				return nil, fmt.Errorf("failed to read file %q: %w", input, err)
   109			}
   110			configFiles = append(configFiles, types.ConfigFile{
   111				Filename: input,
   112				Content:  content,
   113			})
   114		}
   115	
   116		composeProject, err := loader.LoadWithContext(ctx, types.ConfigDetails{
   117			ConfigFiles: configFiles,
   118			Environment: types.NewMapping(env),
   119		}, opts...)
   120		if err != nil {
