   128		}
   129	
   130		// Construct a map of service to container name.
   131		g.serviceToContainerName = map[string]string{}
   132		for _, service := range composeProject.Services {
   133			var name string
   134			if service.ContainerName != "" {
   135				name = service.ContainerName
   136			} else {
   137				name = g.Project.With(service.Name)
   138			}
   139			g.serviceToContainerName[service.Name] = name
   140		}
   141	
   142		networks, networkMap := g.buildNixNetworks(composeProject)
   143		volumes, volumeMap := g.buildNixVolumes(composeProject)
   144		containers, err := g.buildNixContainers(composeProject, networkMap, volumeMap)
   145		if err != nil {
