   170	func (g *Generator) postProcess(composeProject *types.Project, containers []*NixContainer, networks []*NixNetwork, volumes []*NixVolume) ([]*NixNetwork, []*NixVolume) {
   171		// Drop any networks that are unused or external.
   172		networks = slices.DeleteFunc(networks, func(n *NixNetwork) bool {
   173			used := false
   174			for _, c := range containers {
   175				if slices.Contains(c.Networks, n.Name) {
   176					used = true
   177					break
   178				}
   179			}
   180			return (!used && !g.GenerateUnusedResources) || n.External
   181		})
   182	
   183		// Drop any volumes that are unused or external.
   184		volumes = slices.DeleteFunc(volumes, func(v *NixVolume) bool {
   185			used := false
   186			for _, c := range containers {
   187				if _, ok := c.Volumes[v.Name]; ok {
   188					used = true
   189					break
   190				}
   191			}
   192			return (!used && !g.GenerateUnusedResources) || v.External
   193		})
   194		return networks, volumes
   195	}
