   197	func healthCheckCommandToString(cmd []string) (string, error) {
   198		if len(cmd) == 0 {
   199			return "", fmt.Errorf("empty cmd")
   200		}
   201		switch cmd[0] {
   202		case "NONE":
   203			return "", fmt.Errorf("cmd starts with NONE")
   204		case "CMD-SHELL":
   205			return cmd[1], nil
   206		case "CMD":
   207			j, err := json.Marshal(cmd[1:])
   208			if err != nil {
   209				return "", fmt.Errorf("failed to convert %v to JSON: %w", cmd[1:], err)
   210			}
   211			return string(j), nil
   212		}
   213		panic("unreachable")
   214	}
