import java.net.URI;
import java.util.Set;
import com.networknt.schema.InputFormat;
import com.networknt.schema.JsonSchema;
import com.networknt.schema.JsonSchemaFactory;
import com.networknt.schema.SchemaValidatorsConfig;
import com.networknt.schema.SpecVersion.VersionFlag;
import com.networknt.schema.ValidationMessage;

public class TestIriValidation {

    public static void main(String[] args) {
        // Test iri-reference format
        testFormat("iri-reference", VersionFlag.V202012);

        // Test iri format
        testFormat("iri", VersionFlag.V202012);
    }

    public static void testFormat(String formatName, VersionFlag version) {
        System.out.println("\n=== Testing format: " + formatName + " ===");

        String schemaData = "{\r\n"
                + "  \"format\": \"" + formatName + "\"\r\n"
                + "}";

        SchemaValidatorsConfig config = new SchemaValidatorsConfig();
        config.setFormatAssertionsEnabled(true);
        JsonSchema schema = JsonSchemaFactory.getInstance(version).getSchema(schemaData, config);

        // Test 1: Valid URL with no brackets should pass
        testUrl(schema, "Valid URL without brackets", 
                "https://test.com/assets/product.pdf", true);

        // Test 2: Encoded brackets should pass (this is the bug fix!)
        testUrl(schema, "Encoded brackets [test] -> %5Btest%5D", 
                "https://test.com/assets/product.pdf?filter%5Btest%5D=1", true);

        // Test 3: Unencoded brackets should fail
        testUrl(schema, "Unencoded brackets [test]", 
                "https://test.com/assets/product.pdf?filter[test]=1", false);

        // Test 4: IRI with Unicode characters should pass
        testUrl(schema, "IRI with Unicode", 
                "https://test.com/assets/produktdatenblätter.pdf", true);

        // Test 5: Encoded open bracket only
        testUrl(schema, "Encoded open bracket only", 
                "https://test.com/assets/product.pdf?filter%5Btest=1", true);

        // Test 6: Encoded close bracket only
        testUrl(schema, "Encoded close bracket only", 
                "https://test.com/assets/product.pdf?filter=test%5D=1", true);

        // Test 7: Mixed encoded and unencoded (unencoded should fail)
        testUrl(schema, "Mixed: encoded open, unencoded close", 
                "https://test.com/assets/product.pdf?filter%5Btest]=1", false);

        // Test 8: Multiple encoded brackets
        testUrl(schema, "Multiple encoded brackets", 
                "https://test.com/api?filter%5Bname%5D=John%5Bage%5D>30", true);

        // Test 9: Query with no brackets but other special characters
        testUrl(schema, "Query with other special chars", 
                "https://test.com/api?name=John+Doe&city=New%20York", true);

        // Test 10: Empty query string
        testUrl(schema, "Empty query string", 
                "https://test.com/assets/product.pdf?", true);
    }

    public static void testUrl(JsonSchema schema, String testName, String url, boolean shouldPass) {
        Set<ValidationMessage> messages = schema.validate("\"" + url + "\"", InputFormat.JSON);
        boolean passed = messages.isEmpty();

        String status = (passed == shouldPass) ? "✓ PASS" : "✗ FAIL";
        System.out.println(status + " - " + testName);
        System.out.println("   URL: " + url);
        System.out.println("   Expected: " + (shouldPass ? "pass" : "fail") + 
                         ", Got: " + (passed ? "pass" : "fail"));
        if (passed != shouldPass && !messages.isEmpty()) {
            System.out.println("   Error: " + messages);
        }
        System.out.println();
    }
}
